using Ohno.CircleGame.Gameplay;
namespace Ohno.QA12;
public static partial class Tests
{
    static SpinnerState MovingState(double delta=.7)
    {var s=State(7000);s.SampleAngle(0,2200,0,true);s.SampleAngle(delta,2300,0,true);return s;}
    static void Motion()
    {
        foreach(int time in new[]{2199,2200,2201,9199,9200,9201})foreach(int interval in new[]{-1,0,1,29})Add($"U01 strict time{time} interval{interval}","E041 M05f5 strict S<T<E positive interval",()=>{var s=MovingState();var stages=new List<SpinnerSoundStage>();s.Sound+=(_,e)=>stages.Add(e);s.Integrate(time,interval);bool admitted=time>2200&&time<9200&&interval>0;Seq(stages,admitted?[SpinnerSoundStage.Motion]:[]);Eq(s.Progress>0,admitted);});
        foreach(double delta in new[]{-.7,0,.7})Add("U02 signed smoothed U "+delta,"E041 M05f5 fresh Double U not raw or step",()=>{var s=MovingState(delta);float before=s.Progress;double presentation=s.VisualRotation;var stages=new List<SpinnerSoundStage>();s.Sound+=(x,e)=>{Eq(x.Progress,before);Eq(x.VisualRotation!=presentation,delta!=0);stages.Add(e);};s.Integrate(2400,29);Seq(stages,delta==0?[SpinnerSoundStage.ZeroMotion]:[SpinnerSoundStage.Motion]);Eq(Math.Sign(s.SmoothedMotion),Math.Sign(delta));});
        Add("U03 independently established release residual","E024 deceleration;E041 M05f5 uses residual U",()=>{var s=MovingState();Near(s.Acceleration,.00008);s.Integrate(2300,40);s.Integrate(2340,40);Near(s.SmoothedMotion,.0064);s.SampleAngle(1.4,2380,0,false);Eq(s.TargetMotion,0d);Eq(s.InputHeld,false);var stages=new List<SpinnerSoundStage>();s.Sound+=(_,e)=>stages.Add(e);float p=s.Progress;s.Integrate(2380,10);Near(s.SmoothedMotion,.0056);Yes(s.SmoothedMotion!=0,"residual independently proven before loop assertion");Seq(stages,SpinnerSoundStage.Motion);Yes(s.Progress>p,"residual accumulates after callback");});
        Add("U04 repeated controlled timestamp still submits each reached update","E041 no once-per-frame promise",()=>{var s=MovingState();int n=0;s.Sound+=(_,e)=>{if(e==SpinnerSoundStage.Motion)n++;};s.Integrate(2300,29);s.Integrate(2300,29);Eq(n,2);});
        foreach(bool modulate in new[]{false,true})Add("U05 playback independent setting "+modulate,"E041 M05fb/M3b34 optional frequency always queue start",()=>{var f=new Rig();var s=MovingState();s.Sound+=(x,e)=>{if(e==SpinnerSoundStage.Motion)f.Spin.Continue(modulate?(float)x.Observation.Count/x.Required:null);};s.Integrate(2300,29);Eq(f.Global.Pending,1);Eq(f.B.Ops.Count,modulate?2:0);f.Global.Drain();Eq(f.B.Ops[^1].Name,"Play");Eq(f.B.Ops[^1].Flag,false);});
        Add("U06 U nonzero even when Single step underflows","E041 fresh Double U not Single increment;artificial private state",()=>{var s=State(7000);typeof(SpinnerState).GetField("<SmoothedMotion>k__BackingField",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance)!.SetValue(s,1e-100);typeof(SpinnerState).GetField("<TargetMotion>k__BackingField",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance)!.SetValue(s,1e-100);var stages=new List<SpinnerSoundStage>();s.Sound+=(_,e)=>stages.Add(e);s.Integrate(2300,1);Eq(s.Progress,0f);Yes(s.SmoothedMotion!=0,"Double U retained");Seq(stages,SpinnerSoundStage.Motion);});
        Add("U07 zero queues Pause before P","E041 zero-U cleanup boundary",()=>{var f=new Rig();var s=State();s.Sound+=(_,e)=>{if(e==SpinnerSoundStage.ZeroMotion){Eq(s.Progress,0f);f.Spin.QueuePause();}};s.Integrate(2300,29);Eq(f.Global.Pending,1);Eq(f.B.Ops.Count,0);f.Global.Drain();Seq(f.B.Ops.Select(x=>x.Name),"Pause");});
    }
    static void Deferred()
    {
        Add("D01 synchronous modulation separate queued action","E041 M3b34/M3ba3",()=>{var f=new Rig();f.Spin.Continue(.5f);Eq(f.Global.Pending,1);Seq(f.B.Ops.Select(x=>x.Name),"Length","Attribute");f.B.Ops.Clear();f.Global.Drain();Seq(f.B.Ops.Select(x=>x.Name),"Attribute","Play");Eq(f.B.Ops[^1].Flag,false);});
        foreach(int active in new[]{0,1,3})Add("D02 repeat submissions activity "+active,"E041 no active1 or pending start suppression",()=>{var f=new Rig();f.B.States[733]=active;f.Spin.Continue(null);f.Spin.Continue(null);Eq(f.Global.Pending,2);Eq(f.B.Ops.Count,0);f.Global.Drain();Eq(f.B.Ops.Count(o=>o.Name=="Play"),2);Yes(f.B.Ops.All(o=>o.Name!="Activity"),"no activity gate");});
        Add("D03 replace after submission and execute fresh gain","E041 M3ba3 execution gain and target",()=>{var f=new Rig();f.Spin.Continue(null);f.Sample=919;f.Global.Clock(110);f.Global.EffectVolume=100;f.Global.UniversalVolume=100;f.B.Ops.Clear();f.Global.Drain();Seq(f.B.Ops.Select(o=>o.Handle),919,919);Near(f.B.Ops[0].Value,.73,1e-7);Eq(f.B.Ops[^1].Flag,false);});
        Add("D04 replace between Attribute and Play","E041 M3ba3 separate field reads0000/0017",()=>{var f=new Rig();f.Spin.Continue(null);f.B.Enter=o=>{if(o.Name=="Attribute")f.Spin.Channel=919;};f.Global.Drain();Seq(f.B.Ops.Select(o=>o.Handle),733,919);});
        Add("D05 Pause fresh channel after real global replacement","E041 M3ba9 not captured owner",()=>{var f=new Rig();f.Spin.QueuePause();f.Sample=919;f.Global.Clock(110);f.B.Ops.Clear();f.Global.Drain();Seq(f.B.Ops.Select(o=>o.Name),"Pause");Eq(f.B.Ops[0].Handle,919);Eq(f.Spin.Channel,919);});
        Add("D06 pause then reentry start","E041 shared channel Pause distinct from Stop",()=>{var f=new Rig();f.Spin.QueuePause();f.Spin.Continue(null);f.Global.Drain();Seq(f.B.Ops.Select(o=>o.Name),"Pause","Attribute","Play");Eq(f.Spin.Channel,733);});
        Add("D07 timing reset retains shared identity and queued actions","E041 no recovered F2356 zero reset",()=>{var f=new Rig();f.Spin.QueuePause();f.Global.Timing.Reset();Eq(f.Spin.Channel,733);Eq(f.Global.Pending,1);f.Global.Drain();Eq(f.B.Ops.Single().Handle,733);});
        Add("D08 explicit cancellation","ENGINEERING queue cancellation not original scheduler",()=>{var f=new Rig();f.Spin.Continue(null);f.Spin.QueuePause();Eq(f.Global.Pending,2);f.Global.Cancel();f.Global.Drain();Eq(f.B.Ops.Count,0);Eq(f.Spin.Channel,733);});
        foreach(string fail in new[]{"Attribute","Play","Pause"})Add("D09 callback failure "+fail,"E041 pure model propagation;Windows containment separate",()=>{var f=new Rig();if(fail=="Pause")f.Spin.QueuePause();else f.Spin.Continue(null);f.B.Enter=o=>{if(o.Name==fail)throw new IOException(fail);};Throws<IOException>(()=>f.Global.Drain());Eq(f.Global.Pending,0);f.Trace();});
        Add("D10 separate slider and spinner Pause targets","E041 F2356 versus F2354/2355",()=>{var f=new Rig();f.Global.QueuePause();f.Spin.QueuePause();f.Global.Drain();Seq(f.B.Ops.Select(o=>o.Handle),101,202,733);});
    }
}
